import SwiftUI

struct ContactForm: View {
    var initial_name: String = ""
    var initial_email: String = ""
    var submitting: Bool = false
    var server_error: String = ""

    var onSubmit: (([String: String]) -> Void)? = nil
    var onValidationFailed: (([String]) -> Void)? = nil

    @State private var name: String = ""
    @State private var email: String = ""
    @State private var message: String = ""
    @State private var didInit: Bool = false

    private func isValidEmail(_ s: String) -> Bool {
        let pattern = #"^[^\s@]+@[^\s@]+\.[^\s@]+$"#
        return s.range(of: pattern, options: .regularExpression) != nil
    }

    private func validate() -> [String] {
        var invalid: [String] = []
        if name.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            invalid.append("name")
        }
        if !isValidEmail(email) {
            invalid.append("email")
        }
        if message.count < 10 {
            invalid.append("message")
        }
        return invalid
    }

    private func handleSubmit() {
        if submitting { return }
        let invalid = validate()
        if !invalid.isEmpty {
            onValidationFailed?(invalid)
            return
        }
        onSubmit?([
            "name": name,
            "email": email,
            "message": message
        ])
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            Text("Kontaktformular")
                .font(.headline)

            Text("Name")
            TextField("Name", text: $name)
                .textFieldStyle(.roundedBorder)
                .disabled(submitting)

            Text("E-Mail")
            TextField("E-Mail", text: $email)
                .textFieldStyle(.roundedBorder)
                .disabled(submitting)

            Text("Nachricht")
            TextField("Nachricht", text: $message)
                .textFieldStyle(.roundedBorder)
                .disabled(submitting)

            if !server_error.isEmpty {
                Text(server_error)
                    .foregroundColor(.red)
            }

            Button(action: handleSubmit) {
                if submitting {
                    Text("Wird gesendet…")
                } else {
                    Text("Absenden")
                }
            }
            .disabled(submitting)
        }
        .padding()
        .onAppear {
            if !didInit {
                name = initial_name
                email = initial_email
                didInit = true
            }
        }
    }
}
